// Merge real SAP data or mock data into unified format
const input = $input.first().json;
const results = input.d?.results || [];
return [{ json: { d: { results } } }];

const orders = $input.first().json.d.results;

const priorityLabel = (p) => {
  if (p === '1') return '🔴 Very High (P1)';
  if (p === '2') return '🟠 High (P2)';
  return `Priority ${p}`;
};

const statusLabel = (s) => {
  const map = {
    'CRTD': 'Created', 'REL': 'Released', 'PEND': 'Pending',
    'TECO': 'Technically Complete', 'CLSD': 'Closed', 'DLFL': 'Deletion Flag'
  };
  return map[s] || s || 'Unknown';
};

const formatDate = (sapDate) => {
  if (!sapDate) return 'Not set';
  const ms = parseInt(sapDate.replace(/\/Date\((\d+)\)\//, '$1'));
  if (isNaN(ms)) return sapDate;
  return new Date(ms).toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' });
};

const p1Orders = orders.filter(o => o.MaintPriority === '1');
const p2Orders = orders.filter(o => o.MaintPriority === '2');
const ts = new Date().toLocaleString('en-GB', { timeZone: 'Asia/Karachi', hour12: false });

// Plain text for Claude AI
let plain = `SAP Plant Maintenance — IW38 High Priority Orders Report\n`;
plain += `Timestamp: ${ts} PKT\n`;
plain += `Total: ${orders.length} orders (P1 Very High: ${p1Orders.length}, P2 High: ${p2Orders.length})\n\n`;
orders.forEach(o => {
  plain += `───────────────────────────────────\n`;
  plain += `Order#     : ${o.MaintenanceOrder}\n`;
  plain += `Priority   : ${priorityLabel(o.MaintPriority)}\n`;
  plain += `Type       : ${o.MaintOrderType}\n`;
  plain += `Description: ${o.MaintOrderDesc || 'N/A'}\n`;
  plain += `Plant      : ${o.MaintPlant}\n`;
  plain += `Location   : ${o.FunctionalLocation || 'N/A'}\n`;
  plain += `Equipment  : ${o.Equipment || 'N/A'}\n`;
  plain += `Work Center: ${o.MainWorkCenter || 'N/A'}\n`;
  plain += `Responsible: ${o.MaintOrdPersonResponsible || 'Unassigned'}\n`;
  plain += `Start Date : ${formatDate(o.BasicStartDate)}\n`;
  plain += `Due Date   : ${formatDate(o.BasicFinishDate)}\n`;
  plain += `Created On : ${formatDate(o.OrderCreationDate)}\n`;
  plain += `Status     : ${statusLabel(o.MaintOrderSystemStatus)}\n\n`;
});

// HTML table for email
let htmlRows = '';
orders.forEach(o => {
  const bg = o.MaintPriority === '1' ? '#ffe5e5' : '#fff3e0';
  const urgency = o.MaintPriority === '1' ? '🔴 Very High' : '🟠 High';
  htmlRows += `<tr style="background:${bg}">
    <td style="padding:9px 12px;border:1px solid #ddd;font-weight:bold;font-size:13px">${o.MaintenanceOrder}</td>
    <td style="padding:9px 12px;border:1px solid #ddd;font-size:13px">${urgency}</td>
    <td style="padding:9px 12px;border:1px solid #ddd;font-size:13px">${o.MaintOrderType}</td>
    <td style="padding:9px 12px;border:1px solid #ddd;font-size:13px">${o.MaintOrderDesc || '—'}</td>
    <td style="padding:9px 12px;border:1px solid #ddd;font-size:13px">${o.MaintPlant}</td>
    <td style="padding:9px 12px;border:1px solid #ddd;font-size:13px">${o.FunctionalLocation || '—'}</td>
    <td style="padding:9px 12px;border:1px solid #ddd;font-size:13px">${o.Equipment || '—'}</td>
    <td style="padding:9px 12px;border:1px solid #ddd;font-size:13px">${o.MainWorkCenter || '—'}</td>
    <td style="padding:9px 12px;border:1px solid #ddd;font-size:13px">${o.MaintOrdPersonResponsible || '⚠️ Unassigned'}</td>
    <td style="padding:9px 12px;border:1px solid #ddd;font-size:13px">${formatDate(o.BasicStartDate)}</td>
    <td style="padding:9px 12px;border:1px solid #ddd;font-size:13px">${formatDate(o.BasicFinishDate)}</td>
    <td style="padding:9px 12px;border:1px solid #ddd;font-size:13px">${statusLabel(o.MaintOrderSystemStatus)}</td>
  </tr>`;
});

const htmlTable = `<table style="border-collapse:collapse;width:100%;font-family:Arial,sans-serif">
  <thead>
    <tr style="background:#1a237e;color:white">
      <th style="padding:10px 12px;border:1px solid #ddd;text-align:left">Order #</th>
      <th style="padding:10px 12px;border:1px solid #ddd;text-align:left">Priority</th>
      <th style="padding:10px 12px;border:1px solid #ddd;text-align:left">Type</th>
      <th style="padding:10px 12px;border:1px solid #ddd;text-align:left">Description</th>
      <th style="padding:10px 12px;border:1px solid #ddd;text-align:left">Plant</th>
      <th style="padding:10px 12px;border:1px solid #ddd;text-align:left">Location</th>
      <th style="padding:10px 12px;border:1px solid #ddd;text-align:left">Equipment</th>
      <th style="padding:10px 12px;border:1px solid #ddd;text-align:left">Work Center</th>
      <th style="padding:10px 12px;border:1px solid #ddd;text-align:left">Responsible</th>
      <th style="padding:10px 12px;border:1px solid #ddd;text-align:left">Start Date</th>
      <th style="padding:10px 12px;border:1px solid #ddd;text-align:left">Due Date</th>
      <th style="padding:10px 12px;border:1px solid #ddd;text-align:left">Status</th>
    </tr>
  </thead>
  <tbody>${htmlRows}</tbody>
</table>`;

return [{ json: {
  order_count: orders.length,
  p1_count: p1Orders.length,
  p2_count: p2Orders.length,
  orders,
  plain_summary: plain,
  html_table: htmlTable,
  timestamp: ts,
  generated_at: new Date().toISOString()
}}];
